/* v0.11 lightweight inventory UI; no batch objects in daily operations. */
const S=SimpleInventory,$=q=>document.querySelector(q),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,stock,sheet=null,page='inventory',viewMode='grid',addDraft=null,composing=false,pendingDraw=false,homeSearch='',previewItemId=null,lastDrawPage=null,resumeScroll=false,pageScroll={home:0,inventory:0,history:0,settings:0},search='',filter='all',historyFilter='all',busy=false,notice='',noticeOp=null,timer,renderToken=0,lastFocus=null;
const icons={home:'m3 11 9-8 9 8v10h-6v-7H9v7H3Z',box:'m3 7 9-4 9 4-9 4ZM3 7v10l9 4 9-4V7M12 11v10',plus:'M12 5v14M5 12h14',minus:'M5 12h14',history:'M3 12a9 9 0 1 0 3-6M3 3v6h6M12 7v5l3 2',close:'m6 6 12 12M6 18 18 6',settings:'M9 3h6l1 3 3 1 2 5-2 3-1 4-4 2-4-2-4-1-2-5 2-3 1-4Z'};
function icon(n){if(n==='settings'){const p=Array.from({length:8},(_,i)=>[-22.5,-12,12,22.5].map((a,j)=>{const r=j===0||j===3?8:10,t=(i*45+a-90)*Math.PI/180;return `${(12+r*Math.cos(t)).toFixed(3)},${(12+r*Math.sin(t)).toFixed(3)}`;})).flat();return `<svg class="glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="M${p.join('L')}Z"/><circle cx="12" cy="12" r="3.25"/></svg>`;}return `<svg class="glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;}
const button=(action,label,cls='secondary',id='')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}" ${busy?'disabled':''}>${label}</button>`;
const field=(name,label,value='',attrs='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" value="${esc(value)}" ${attrs}></div>`;
function formRead(){const a=activeForm();if(!a)return;for(const name of ['itemName','brandName','specName','quantity','location','amount','direction','minimum','name']){const el=$('#'+name);if(el)a[name]=el.value;}readUnitField(a);if($('#enabled'))a.enabled=$('#enabled').checked;if($('#restoreAck'))a.ack=$('#restoreAck').checked;if($('#restoreArchived'))a.restoreArchived=$('#restoreArchived').checked;}
function variant(id){return stock.variants.find(v=>v.id===id);}
function itemVariants(i){const bs=stock.brands.filter(b=>b.itemId===i.id).map(b=>b.id);return stock.variants.filter(v=>bs.includes(v.brandId)&&!v.hidden);}
function itemQty(i){return itemVariants(i).reduce((n,v)=>n+v.quantity,0);}
function low(i){return !i.archived&&i.reminderEnabled&&itemQty(i)<=i.minStock;}
function feedback(message,op=null){notice=message;noticeOp=op;clearTimeout(timer);timer=setTimeout(()=>{notice='';noticeOp=null;draw();},op?9000:4000);timer?.unref?.();}
function identity(v){const c=S.context(stock,v);return `<div class="maintenance-identity"><strong>${esc(c.item)}</strong><span>${esc(c.brand)} · ${esc(c.spec)}</span><small>当前 ${v.quantity} ${esc(c.unit)}</small></div>`;}
function stockRow(v,compact=false){const c=S.context(stock,v);return `<div class="sku-row" data-variant="${esc(v.id)}"><button class="sku-info" data-action="edit" data-id="${esc(v.id)}"><strong>${esc(compact?v.name:c.brand+' · '+v.name)}</strong><span>${esc(v.location||'未记录位置')}</span><small>编辑品牌、规格与位置</small></button><div class="sku-stepper"><button class="quantity-action minus" data-action="minus" data-id="${esc(v.id)}" aria-label="减少${esc(c.item+' '+c.brand+' '+c.spec)}一${esc(c.unit)}" ${busy||v.quantity===0?'disabled':''}>${icon('minus')}</button><button class="sku-quantity" data-action="amount" data-id="${esc(v.id)}" aria-label="调整${esc(c.item+' '+c.brand+' '+c.spec)}数量">${v.quantity}<small>${esc(c.unit)}</small></button><button class="quantity-action plus" data-action="plus" data-id="${esc(v.id)}" aria-label="增加${esc(c.item+' '+c.brand+' '+c.spec)}一${esc(c.unit)}" ${busy?'disabled':''}>${icon('plus')}</button></div></div>`;}
function inventoryView(){return renderList();}
const labels={IN:'增加',OUT:'减少',REVERSE:'撤销',EDIT:'规格编辑',ITEM_EDIT:'品类编辑',MINIMUM:'补货设置',DELETE:'删除规格',CREATE:'建立产品',ARCHIVE:'归档产品',UNARCHIVE:'取消归档',ICON:'更换图标'};
function homeView(){return renderGrid();}
function previewBody(itemId){const i=stock.items.find(i=>i.id===itemId);if(!i||i.archived)return '<p class="note">该品类已不存在，请关闭后刷新。</p>';const vs=itemVariants(i);return `${button('item','编辑产品与提醒','text-button',i.id)}<p class="note preview-hint">点 ＋／－ 调整 1，点数量可调整多个。</p><div class="preview-groups">${stock.brands.filter(b=>b.itemId===i.id&&vs.some(v=>v.brandId===b.id)).map(b=>`<section class="preview-brand"><h3>${esc(b.name)}</h3>${vs.filter(v=>v.brandId===b.id).map(v=>stockRow(v,true)).join('')}</section>`).join('')||'<p class="note">暂无可见规格，可以添加新规格。</p>'}</div>`;}
function historyView(){const rows=stock.operations.filter(o=>historyFilter==='all'||o.type===historyFilter).slice().reverse();return `<section class="page-heading"><span class="eyebrow">每次变化都有记录</span><h1>操作流水</h1></section><div class="filter-chips">${[['all','全部'],['IN','增加'],['OUT','减少'],['REVERSE','撤销'],['EDIT','编辑'],['ARCHIVE','归档'],['UNARCHIVE','恢复'],['DELETE','删除']].map(([id,n])=>button('historyFilter',n,id===historyFilter?'selected':'',id)).join('')}</div>${rows.map(o=>`<button class="movement-row" data-action="audit" data-id="${esc(o.id)}"><span class="movement-icon ${o.type==='IN'?'in':o.type==='OUT'?'out':'info'}">${icon(o.delta<0?'minus':'history')}</span><span class="movement-copy"><strong>${esc(o.label?.item||'库存记录')}</strong><span>${esc([o.label?.brand,o.label?.spec].filter(Boolean).join(' · '))}</span><small>${labels[o.type]}${o.reversedBy?' · 已撤销':''} · ${esc(new Date(o.at).toLocaleString('zh-CN'))}</small></span><span class="movement-delta">${o.delta==null?({CREATE:'建档',ARCHIVE:'归档',UNARCHIVE:'恢复',ICON:'图标'}[o.type]||'编辑'):(o.delta>0?'+':'')+o.delta}</span></button>`).join('')||'<div class="empty-state"><p>简化后的增减会在这里记录。</p></div>'}<section class="panel legacy-note"><h3>旧版历史已归档</h3><p>${stock.legacyArchive.tables.movements.length} 条原数量流水、${stock.legacyArchive.tables.operations.length} 条原操作记录均保留。</p>${button('legacy','查看旧版流水')}${button('exportLegacy','导出旧版归档','text-button')}</section>`;}
function settingsView(){return `<section class="page-heading"><h1>设置与数据</h1></section><section class="panel"><h2>完整库存备份</h2><p>数据仍保存在当前设备，建议定期将 JSON 保存到“文件”App。备份包含当前规格库存、位置、提醒、操作流水及完整旧版归档。</p>${button('export','导出完整备份','primary wide')}<div class="divider"></div><label class="file-button" for="importFile">从 JSON 恢复</label><input id="importFile" type="file" accept="application/json,.json"><p class="note">支持简化版和旧版备份；确认前先预览差异，恢复前自动保留快照。</p></section><section class="panel"><h2>恢复前快照</h2><div id="recoveries">正在读取…</div></section><section class="panel"><h2>已归档产品</h2><p>不再购买的产品可归档，以后随时恢复。</p>${button('archives','管理已归档产品（'+stock.items.filter(i=>i.archived).length+'）','secondary wide')}</section>`;}
function dialog(){if(!sheet)return '';const a=sheet;let title='',body='',footer='';const close=button('close','取消','secondary'),managed=managementDialog(a);if(managed){title=managed.title;body=managed.body;footer=managed.footer;}else if(a.type==='preview'){title=stock.items.find(i=>i.id===a.itemId)?.name||'物品';body=previewBody(a.itemId);footer=button('close','关闭')+button('addFor','添加规格','primary',a.itemId);}else if(a.type==='add'){title='增加库存';const i=stock.items.find(i=>i.name.trim().toLowerCase()===String(a.itemName||'').trim().toLowerCase());body=field('itemName','品类名称',a.itemName,'maxlength="100" list="itemNames"')+`<datalist id="itemNames">${stock.items.map(i=>`<option value="${esc(i.name)}">`).join('')}</datalist>`+field('brandName','品牌',a.brandName,'maxlength="100" list="brandNames"')+`<datalist id="brandNames">${stock.brands.filter(b=>b.itemId===i?.id).map(b=>`<option value="${esc(b.name)}">`).join('')}</datalist>`+field('specName','规格',a.specName,'maxlength="100" list="specNames"')+`<datalist id="specNames">${stock.variants.filter(v=>!v.hidden&&stock.brands.find(b=>b.id===v.brandId)?.itemId===i?.id).map(v=>`<option value="${esc(v.name)}">`).join('')}</datalist>`+field('quantity','增加数量',a.quantity,'type="number" inputmode="numeric" min="1" max="999999999" step="1"')+(i?`<p class="note">已有品类，单位沿用 ${esc(i.unit)}；相同品牌规格直接累加。</p>`:field('unit','计数单位',a.unit,'maxlength="20"'))+field('location','存放位置（新规格，可留空）',a.location,'maxlength="5000"')+'<p class="note">已有规格保留原位置，需修改时请在库存中编辑。</p>';footer=close+button('save','确认增加','primary');}
 else if(['amount','edit','delete'].includes(a.type)){const v=variant(a.variantId);body=identity(v);if(a.type==='amount'){title='调整数量';body+=`<div class="field"><label for="direction">操作</label><select id="direction"><option value="1" ${a.direction==='1'?'selected':''}>增加</option><option value="-1" ${a.direction==='-1'?'selected':''}>减少</option></select></div>`+field('amount','本次数量',a.amount,'type="number" inputmode="numeric" min="1" max="999999999" step="1"');footer=close+button('save','确认调整',a.direction==='-1'?'consume':'primary');}else if(a.type==='edit'){title='编辑品牌规格与位置';body+=field('brandName','品牌',a.brandName,'maxlength="100"')+field('specName','规格',a.specName,'maxlength="100"')+`<div class="field"><label for="location">存放位置</label><textarea id="location" rows="3" maxlength="5000">${esc(a.location)}</textarea></div><p class="note">只修改当前这条规格库存，数量保持不变。</p><div class="delete-batch-area">${button('delete','删除这条规格库存','delete-batch-button',v.id)}</div>`;footer=close+button('save','保存修改','primary');}else{title='删除规格库存';body+='<p class="delete-warning">确认移除此规格的全部剩余库存？其他规格不受影响。原记录与删除流水保留，删除暂不支持单独撤销。</p>';footer=button('cancelDelete','取消','secondary')+button('save','确认删除','danger');}}
 else if(a.type==='item'){const i=stock.items.find(i=>i.id===a.itemId);title='品类与补货提醒';body=field('name','品类名称',a.name,'maxlength="100"')+`<p class="note">当前共 ${itemQty(i)} ${esc(i.unit)}，单位不变。</p><label class="reminder-switch"><input id="enabled" type="checkbox" ${a.enabled?'checked':''}>开启补货提醒</label>`+field('minimum',`最低库存（${esc(i.unit)}）`,a.minimum,'type="number" inputmode="numeric" min="0" step="1"')+'<p class="note">名称修改影响整个品类；库存 ≤ 最低库存时提醒。</p>';footer=close+button('save','保存','primary');}
 else if(a.type==='undo'){const o=stock.operations.find(o=>o.id===a.operationId);title='撤销操作';body=`<div class="maintenance-identity"><strong>${esc(o.label.item)}</strong><span>${esc(o.label.brand)} · ${esc(o.label.spec)}</span></div><p>将反向调整 ${Math.abs(o.delta)} ${esc(o.label.unit)}，保留原记录和撤销流水。</p>`;footer=close+button('save','确认撤销','consume');}
 else if(a.type==='audit'){const o=stock.operations.find(o=>o.id===a.operationId);title=labels[o.type];body=`<div class="maintenance-identity"><strong>${esc(o.label?.item)}</strong><span>${esc([o.label?.brand,o.label?.spec].filter(Boolean).join(' · '))}</span></div><p>${esc(new Date(o.at).toLocaleString('zh-CN'))}</p>${o.delta!=null?`<p class="audit-delta">${o.beforeQuantity} → ${o.afterQuantity}（${o.delta>0?'+':''}${o.delta}）</p>`:''}${o.before!=null?`<div class="change-row"><strong>原信息</strong><span>${esc(typeof o.before==='string'?o.before:JSON.stringify(o.before))}</span><strong>新信息</strong><span>${esc(typeof o.after==='string'?o.after:JSON.stringify(o.after))}</span></div>`:''}${o.reversedBy?'<p>本操作已撤销。</p>':''}`;footer=button('close','关闭')+(S.canUndo(stock,o.id)?button('undo','撤销这次操作','consume',o.id):'');}
 else if(a.type==='restore'){title='恢复前核对';const current=S.summary(stock),incoming=S.summary(a.incoming);body=`<div class="form-notice">恢复会替换当前库存与流水。原库存先自动保留为恢复前快照；此操作不是追加导入。</div><p>规格库存：${current.length} → ${incoming.length} 条</p><p>简化版操作记录：${stock.operations.length} → ${a.incoming.operations.length} 条</p><div class="migration-table">${restoreRows(current,incoming)}${restoreSettings(stock,a.incoming)}</div>`;footer=close+button('save','确认恢复','danger').replace('<button ','<button id="confirmRestore" '+(!a.ack?'disabled ':''));}
 else if(a.type==='legacy'){title='旧版操作流水';const d=stock.legacyArchive.tables;body=`<p class="note">迁移前记录只读保留。更多批次元数据可导出归档查看。</p><div class="migration-table">${[...d.movements,...d.operations.filter(o=>o.type==='EDIT').map(o=>({...o,delta:null}))].sort((a,b)=>b.at.localeCompare(a.at)).map(m=>{const b=d.batches.find(b=>b.id===m.batchId),v=d.variants.find(v=>v.id===b?.variantId),brand=d.brands.find(b=>b.id===v?.brandId),i=d.items.find(i=>i.id===brand?.itemId);return `<div class="change-row"><strong>${esc(i?.name)} · ${esc(brand?.name)} · ${esc(v?.name)}</strong><span>${esc(m.type==='EDIT'?'信息编辑':m.type)} · ${m.delta==null?'数量不变':(m.delta>0?'+':'')+m.delta} · ${esc(new Date(m.at).toLocaleString('zh-CN'))}</span>${m.changes?`<span>${esc(JSON.stringify(m.changes))}</span>`:''}</div>`;}).join('')}</div>`;footer=button('close','关闭')+button('exportLegacy','导出完整旧归档','primary');}
 return `<div class="sheet-back" data-action="close"></div><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheetTitle"><div class="sheet-header"><div class="handle"></div><h2 id="sheetTitle">${title}</h2></div><div class="sheet-body">${a.error?`<div class="form-notice" role="alert">${esc(a.error)}</div>`:''}${body}</div><div class="sheet-footer">${a.type==='restore'?`<label class="restore-ack"><input id="restoreAck" type="checkbox" ${a.ack?'checked':''}>已核对差异，确认替换</label>`:''}<div class="audit-actions">${footer}</div></div></section>`;
}
function restoreRows(current,incoming){const old=new Map(current.map(r=>[r.id,r])),next=new Map(incoming.map(r=>[r.id,r]));return [...new Set([...old.keys(),...next.keys()])].map(id=>{const a=old.get(id),b=next.get(id);if(JSON.stringify(a)===JSON.stringify(b))return '';return `<div class="change-row"><strong>${esc((b||a).item)} · ${esc((b||a).brand)} · ${esc((b||a).spec)}</strong><span>原：${esc(a?[a.item,a.brand,a.spec].join(' · '):'不存在')}</span><span>新：${esc(b?[b.item,b.brand,b.spec].join(' · '):'不存在')}</span><span>数量：${a?.quantity??'不存在'} → ${b?.quantity??'不存在'}</span><span>单位：${esc(a?.unit||'—')} → ${esc(b?.unit||'—')}</span><span>位置：${esc(a?.location||'未记录')} → ${esc(b?.location||'未记录')}</span><span>归档：${a?.archived?'是':'否'} → ${b?.archived?'是':'否'}</span></div>`;}).join('')||'<p>规格数量与位置未变化；仍会替换流水与提醒设置。</p>';}
function restoreSettings(a,b){const old=new Map(a.items.map(i=>[i.id,i])),next=new Map(b.items.map(i=>[i.id,i]));const rows=[...new Set([...old.keys(),...next.keys()])].map(id=>{const x=old.get(id),y=next.get(id);if(x?.minStock===y?.minStock&&x?.reminderEnabled===y?.reminderEnabled&&!!x?.archived===!!y?.archived&&(x?.icon||'auto')===(y?.icon||'auto'))return '';return `<div class="change-row"><strong>产品设置 · ${esc((y||x).name)}</strong><span>${x?(x.reminderEnabled?'开启':'关闭')+' / '+x.minStock:'不存在'} → ${y?(y.reminderEnabled?'开启':'关闭')+' / '+y.minStock:'不存在'}</span><span>归档：${x?.archived?'是':'否'} → ${y?.archived?'是':'否'}；图标：${esc(x?.icon||'auto')} → ${esc(y?.icon||'auto')}</span></div>`;}).join('');const before=new Map(a.operations.map(o=>[o.id,o])),after=new Map(b.operations.map(o=>[o.id,o]));return rows+`<div class="change-row"><strong>流水差异</strong><span>新增 ${b.operations.filter(o=>!before.has(o.id)).length}，移除 ${a.operations.filter(o=>!after.has(o.id)).length}，更新 ${b.operations.filter(o=>before.has(o.id)&&JSON.stringify(before.get(o.id))!==JSON.stringify(o)).length}</span><span>旧版归档流水 ${a.legacyArchive.tables.movements.length} → ${b.legacyArchive.tables.movements.length}，旧版操作 ${a.legacyArchive.tables.operations.length} → ${b.legacyArchive.tables.operations.length}</span></div>`;}
async function draw(){if(composing){pendingDraw=true;return;}if(lastDrawPage===page&&!sheet&&!resumeScroll)pageScroll[page]=window.scrollY||0;const token=++renderToken,active=document.activeElement,focusId=active?.id,start=active?.selectionStart,scroll=$('.sheet-body')?.scrollTop||0;const current=await S.ensure(db);if(token!==renderToken)return;stock=current;S.validate(stock);viewMode=stock.preferences?.view||'grid';if(page==='add'&&!addDraft)addDraft=freshProduct();if(sheet?.type==='preview'&&stock.items.find(i=>i.id===sheet.itemId)?.archived){sheet=null;previewItemId=null;}$('#app').innerHTML=`<main class="app" ${sheet?'inert':''}><header class="app-header"><div class="wordmark"><img src="icon-hamster-192.png" width="32" height="32" alt=""><span>囤囤管家</span></div><span class="local-status">本机保存</span></header>${page==='add'?newProductPage():page==='history'?historyView():page==='settings'?settingsView():inventoryPage()}</main><nav class="nav" aria-label="主导航" ${sheet?'inert':''}>${[['inventory','库存','box'],['add','新增','plus'],['history','流水','history'],['settings','设置','settings']].map(([id,n,ic])=>`<button data-action="nav" data-id="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${icon(ic)}</span><span>${n}</span></button>`).join('')}</nav>${dialog()}${notice?`<div class="toast" role="status"><span>${esc(notice)}</span>${noticeOp?button('undo','撤销','text-button',noticeOp):''}</div>`:''}`;document.body.classList.toggle('sheet-open',!!sheet);const body=$('.sheet-body');if(body)body.scrollTop=scroll;if(focusId&&$('#'+focusId)){const el=$('#'+focusId);el.focus({preventScroll:true});if(start!=null&&['text','search'].includes(el.type))el.setSelectionRange(start,start);}measure();window.scrollTo?.({top:pageScroll[page]||0,behavior:'instant'});lastDrawPage=page;resumeScroll=false;if(page==='settings')await recoveries();}
function download(obj,name){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`囤囤管家_${name}_${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function recoveries(){const rows=await Inventory.transaction(db,['recovery'],tx=>Inventory.request(tx.objectStore('recovery').getAll()),'readonly'),el=$('#recoveries');if(el)el.innerHTML=rows.slice().reverse().map(r=>`<div class="recovery-row"><span>${esc(new Date(r.at).toLocaleString('zh-CN'))}</span>${button('recovery','下载快照','text-button',r.id)}</div>`).join('')||'<p class="note">暂无恢复前快照</p>';}
async function save(){const a=sheet;formRead();a.error='';if(a.type==='add'){const o=await S.add(db,{...a,quantity:Number(a.quantity)});feedback('已增加库存',o.id);}else if(a.type==='amount'){const q=Number(a.amount);if(!Number.isSafeInteger(q)||q<1)throw Error('请填写正整数数量');const o=await S.change(db,{variantId:a.variantId,delta:q*Number(a.direction),expected:a.expected});feedback('数量已更新',o.id);}else if(a.type==='edit'){await S.edit(db,a);feedback('规格与位置已更新');}else if(a.type==='item'){await S.updateItem(db,{itemId:a.itemId,name:a.name,iconKey:a.iconKey,value:Number(a.minimum),enabled:a.enabled,expectedState:a.expectedState});feedback('品类与补货设置已更新');}else if(a.type==='archive'){await S.archive(db,a);if(a.archived)previewItemId=null;feedback(a.archived?'产品已归档，数据完整保留':'产品已恢复');}else if(a.type==='undo'){await S.undo(db,a.operationId);feedback('已撤销，反向流水已保留');}else if(a.type==='delete'){await S.remove(db,a);feedback('已移除规格库存，历史记录保留');}else if(a.type==='restore'){if(!a.ack)throw Error('请先核对并勾选确认');await S.restore(db,a.backup,a.expectedState);feedback('恢复成功，原数据已保存为快照');}sheet=a.type==='archive'&&a.draft?.type==='archives'?{type:'archives'}:previewItemId?{type:'preview',itemId:previewItemId}:null;}
async function action(action,id){if(await managementAction(action,id))return;if(action==='preview'){const i=stock.items.find(i=>i.id===id);if(!i||i.archived)throw Error('产品已归档或已变化，请刷新');pageScroll[page]=window.scrollY||0;previewItemId=id;sheet={type:'preview',itemId:id};return;}if(action==='clearHome'){homeSearch='';return;}if(action==='filter'){filter=id;return;}if(action==='clear'){search='';filter='all';return;}if(action==='historyFilter'){historyFilter=id;return;}if(action==='nav'){pageScroll[page]=window.scrollY||0;sheet=null;previewItemId=null;resumeScroll=true;page=id;return;}if(action==='close'){if(sheet?.type==='delete')sheet=sheet.draft;else if(previewItemId&&sheet?.type!=='preview')sheet={type:'preview',itemId:previewItemId};else{sheet=null;previewItemId=null;resumeScroll=true;}return;}if(action==='migrate'){stock=await S.ensure(db);return;}if(action==='export'){download(await S.backup(db),'完整备份');feedback('备份已生成，请确认保存到文件 App');return;}if(action==='exportLegacy'){download(await Inventory.sealBackup(stock.legacyArchive),'旧版完整归档');return;}if(action==='recovery'){const row=await Inventory.transaction(db,['recovery'],tx=>Inventory.request(tx.objectStore('recovery').get(id)),'readonly');download(row.simpleState?await S.seal({format:'tuntun-simple-backup',version:1,exportedAt:new Date().toISOString(),state:row.simpleState}):await Inventory.sealBackup(row.backup),'恢复前快照');return;}if(action==='legacy'){sheet={type:'legacy'};return;}if(action==='audit'){sheet={type:'audit',operationId:id};return;}if(action==='undo'){if(!S.canUndo(stock,id))throw Error('该操作已有后续变化或已撤销');sheet={type:'undo',operationId:id};return;}if(action==='save'){await save();return;}if(action==='cancelDelete'){sheet=sheet.draft;return;}if(action==='delete'){formRead();sheet={type:'delete',variantId:id,expected:{...sheet.expected},draft:{...sheet}};return;}if(action==='item'){const i=stock.items.find(i=>i.id===id);sheet={type:'item',itemId:id,name:i.name,minimum:i.minStock,enabled:i.reminderEnabled,iconKey:i.icon||'auto',expectedState:S.stateKey(i)};return;}if(action==='add'||action==='addFor'){const i=stock.items.find(i=>i.id===id);sheet={type:'add',itemName:i?.name||'',brandName:'',specName:'',quantity:1,unit:i?.unit||'件',location:''};return;}const v=variant(id);if(!v||v.hidden)throw Error('库存已变化，请刷新');if(action==='plus'||action==='minus'){const o=await S.change(db,{variantId:id,delta:action==='plus'?1:-1});feedback(`${action==='plus'?'已增加':'已减少'} 1 ${S.context(stock,v).unit}`,o.id);return;}if(action==='amount'){sheet={type:'amount',variantId:id,amount:1,direction:'1',expected:{quantity:v.quantity,revision:v.revision}};return;}if(action==='edit'){sheet={type:'edit',variantId:id,brandName:S.context(stock,v).brand,specName:v.name,location:v.location,expected:{quantity:v.quantity,revision:v.revision}};}}
async function perform(a,id){if(busy)return;if(!sheet)pageScroll[page]=window.scrollY||0;busy=true;try{await action(a,id);}catch(e){const a=activeForm();if(a)a.error=e.message;else feedback(e.message);}finally{busy=false;await draw();if(sheet&&!['close','cancelDelete','save'].includes(a))$('.sheet input,.sheet button')?.focus({preventScroll:true});}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();perform(el.dataset.action,el.dataset.id);});
document.addEventListener('input',handleProductInput);
document.addEventListener('compositionstart',()=>{composing=true;});
document.addEventListener('compositionend',endComposition);
document.addEventListener('change',async e=>{if(unitChanged(e))return;if(e.target.id==='direction'){formRead();draw();return;}if(e.target.id!=='importFile'){formRead();if(e.target.id==='restoreAck'&&sheet?.type==='restore'){const confirm=$('#confirmRestore');if(confirm)confirm.disabled=busy||!sheet.ack;}return;}const file=e.target.files?.[0];if(!file||busy)return;busy=true;try{if(file.size>50*1024*1024)throw Error('备份文件过大');const obj=JSON.parse(await file.text()),incoming=await S.decode(obj);sheet={type:'restore',backup:obj,incoming,expectedState:S.stateKey(stock),ack:false};}catch(e){feedback('读取失败：'+e.message);}finally{busy=false;await draw();}});
document.addEventListener('keydown',e=>{if(!sheet)return;if(e.key==='Escape'&&!busy){e.preventDefault();perform('close');}if(e.key==='Tab'){const nodes=[...document.querySelectorAll('.sheet button,.sheet input,.sheet textarea,.sheet select')].filter(n=>!n.disabled&&n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||!nodes.includes(document.activeElement))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||!nodes.includes(document.activeElement))){e.preventDefault();first?.focus();}}});
function measure(){const nav=$('.nav');if(nav)document.documentElement.style.setProperty('--nav-height',nav.getBoundingClientRect().height+'px');}
function keyboard(){const v=window.visualViewport;if(!v)return;const bottom=Math.max(0,innerHeight-v.height-v.offsetTop);document.documentElement.style.setProperty('--keyboard-bottom',bottom+'px');document.documentElement.style.setProperty('--visible-height',v.height+'px');document.body.classList.toggle('keyboard-open',bottom>120);}
window.visualViewport?.addEventListener('resize',keyboard);window.visualViewport?.addEventListener('scroll',keyboard);window.addEventListener('resize',measure);window.addEventListener('offline',()=>{feedback('已离线，仍可记录本机库存');draw();});
async function start(){if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(r=>r.update()).catch(console.warn);try{$('#app').innerHTML='<main class="app"><h1>正在打开库存…</h1><p class="note">正在读取本机数据，请稍候。</p></main>';db=await Inventory.open();if(!await Inventory.preserveExisting(db)){const r=await fetch('./seed.json');if(!r.ok)throw Error('初始库存读取失败');await Inventory.seed(db,await r.json());}await draw();keyboard();}catch(e){$('#app').innerHTML=`<main class="app"><h1>暂时无法打开库存</h1><p>原数据没有重置，请关闭其他页面后重试。</p><p class="field-error">${esc(e.message)}</p><button onclick="location.reload()" class="secondary">重新加载</button></main>`;}}
start();
